-- OpsGrid local MSSQL schema
-- Generated by hand from ../entities/* per the base44-to-local workflow.
-- Apply this to your local MSSQL instance before starting the backend.

IF OBJECT_ID('Users', 'U') IS NULL
CREATE TABLE Users (
    id            NVARCHAR(36)  NOT NULL PRIMARY KEY,
    email         NVARCHAR(255) NOT NULL UNIQUE,
    password_hash NVARCHAR(255) NOT NULL,
    full_name     NVARCHAR(255) NULL,
    role          NVARCHAR(50)  NOT NULL DEFAULT 'user',
    created_date  DATETIME2     NOT NULL DEFAULT GETDATE(),
    updated_date  DATETIME2     NULL
);

IF OBJECT_ID('Action', 'U') IS NULL
CREATE TABLE Action (
    id           NVARCHAR(36)  NOT NULL PRIMARY KEY,
    name         NVARCHAR(255) NOT NULL,
    type         NVARCHAR(50)  NOT NULL,
    status       NVARCHAR(50)  NOT NULL DEFAULT 'pending',
    triggered_by NVARCHAR(255) NULL,
    result       NVARCHAR(MAX) NULL,
    is_critical  BIT           NOT NULL DEFAULT 0,
    created_date DATETIME2     NOT NULL DEFAULT GETDATE(),
    updated_date DATETIME2     NULL
);

IF OBJECT_ID('Alert', 'U') IS NULL
CREATE TABLE Alert (
    id              NVARCHAR(36)  NOT NULL PRIMARY KEY,
    type            NVARCHAR(255) NOT NULL,
    severity        NVARCHAR(50)  NOT NULL,
    message         NVARCHAR(MAX) NOT NULL,
    status          NVARCHAR(50)  NOT NULL DEFAULT 'active',
    source          NVARCHAR(255) NULL,
    acknowledged_by NVARCHAR(255) NULL,
    resolved_at     DATETIME2     NULL,
    created_date    DATETIME2     NOT NULL DEFAULT GETDATE(),
    updated_date    DATETIME2     NULL
);

IF OBJECT_ID('AutomationRule', 'U') IS NULL
CREATE TABLE AutomationRule (
    id              NVARCHAR(36)  NOT NULL PRIMARY KEY,
    name            NVARCHAR(255) NOT NULL,
    trigger_type    NVARCHAR(50)  NOT NULL,
    trigger_config  NVARCHAR(MAX) NULL,
    action_type     NVARCHAR(50)  NOT NULL,
    action_config   NVARCHAR(MAX) NULL,
    status          NVARCHAR(50)  NOT NULL DEFAULT 'active',
    triggered_count FLOAT         NOT NULL DEFAULT 0,
    last_triggered  DATETIME2     NULL,
    created_date    DATETIME2     NOT NULL DEFAULT GETDATE(),
    updated_date    DATETIME2     NULL
);

IF OBJECT_ID('Computer', 'U') IS NULL
CREATE TABLE Computer (
    id            NVARCHAR(36)  NOT NULL PRIMARY KEY,
    name          NVARCHAR(255) NOT NULL,
    status        NVARCHAR(50)  NOT NULL DEFAULT 'idle',
    notes         NVARCHAR(MAX) NULL,
    has_cpu       BIT           NOT NULL DEFAULT 1,
    has_ram       BIT           NOT NULL DEFAULT 1,
    has_storage   BIT           NOT NULL DEFAULT 1,
    has_gpu       BIT           NOT NULL DEFAULT 0,
    cpu_usage     FLOAT         NOT NULL DEFAULT 0,
    ram_usage     FLOAT         NOT NULL DEFAULT 0,
    storage_usage FLOAT         NOT NULL DEFAULT 0,
    gpu_usage     FLOAT         NOT NULL DEFAULT 0,
    simulation_id NVARCHAR(36)  NULL,
    created_date  DATETIME2     NOT NULL DEFAULT GETDATE(),
    updated_date  DATETIME2     NULL
);

IF OBJECT_ID('Dashboard', 'U') IS NULL
CREATE TABLE Dashboard (
    id            NVARCHAR(36)  NOT NULL PRIMARY KEY,
    name          NVARCHAR(255) NOT NULL,
    description   NVARCHAR(MAX) NULL,
    layout_config NVARCHAR(MAX) NULL,
    is_default    BIT           NOT NULL DEFAULT 0,
    profile_type  NVARCHAR(50)  NOT NULL DEFAULT 'operations',
    created_date  DATETIME2     NOT NULL DEFAULT GETDATE(),
    updated_date  DATETIME2     NULL
);

IF OBJECT_ID('Event', 'U') IS NULL
CREATE TABLE Event (
    id          NVARCHAR(36)  NOT NULL PRIMARY KEY,
    type        NVARCHAR(50)  NOT NULL,
    description NVARCHAR(MAX) NOT NULL,
    user_email  NVARCHAR(255) NULL,
    metadata    NVARCHAR(MAX) NULL,
    created_date DATETIME2    NOT NULL DEFAULT GETDATE(),
    updated_date DATETIME2    NULL
);

IF OBJECT_ID('Incident', 'U') IS NULL
CREATE TABLE Incident (
    id          NVARCHAR(36)  NOT NULL PRIMARY KEY,
    title       NVARCHAR(255) NOT NULL,
    alert_id    NVARCHAR(36)  NULL,
    status      NVARCHAR(50)  NOT NULL DEFAULT 'open',
    priority    NVARCHAR(50)  NOT NULL DEFAULT 'medium',
    assigned_to NVARCHAR(255) NULL,
    root_cause  NVARCHAR(MAX) NULL,
    timeline    NVARCHAR(MAX) NULL,
    resolved_at DATETIME2     NULL,
    description NVARCHAR(MAX) NULL,
    created_date DATETIME2    NOT NULL DEFAULT GETDATE(),
    updated_date DATETIME2    NULL
);

IF OBJECT_ID('Metric', 'U') IS NULL
CREATE TABLE Metric (
    id          NVARCHAR(36)  NOT NULL PRIMARY KEY,
    name        NVARCHAR(255) NOT NULL,
    value       FLOAT         NOT NULL,
    unit        NVARCHAR(50)  NULL,
    category    NVARCHAR(50)  NOT NULL DEFAULT 'custom',
    service     NVARCHAR(255) NULL,
    created_date DATETIME2    NOT NULL DEFAULT GETDATE(),
    updated_date DATETIME2    NULL
);

IF OBJECT_ID('Simulation', 'U') IS NULL
CREATE TABLE Simulation (
    id               NVARCHAR(36)  NOT NULL PRIMARY KEY,
    name             NVARCHAR(255) NOT NULL,
    type             NVARCHAR(50)  NOT NULL,
    status           NVARCHAR(50)  NOT NULL DEFAULT 'idle',
    speed            FLOAT         NOT NULL DEFAULT 1,
    parameters       NVARCHAR(MAX) NULL,
    duration_seconds FLOAT         NOT NULL DEFAULT 60,
    events_generated FLOAT         NOT NULL DEFAULT 0,
    created_date     DATETIME2     NOT NULL DEFAULT GETDATE(),
    updated_date     DATETIME2     NULL
);

IF OBJECT_ID('Workspace', 'U') IS NULL
CREATE TABLE Workspace (
    id              NVARCHAR(36)  NOT NULL PRIMARY KEY,
    name            NVARCHAR(255) NOT NULL,
    type            NVARCHAR(50)  NOT NULL,
    description     NVARCHAR(MAX) NULL,
    dashboard_links NVARCHAR(MAX) NULL,
    is_shared       BIT           NOT NULL DEFAULT 0,
    color           NVARCHAR(50)  NOT NULL DEFAULT 'blue',
    icon            NVARCHAR(50)  NOT NULL DEFAULT 'monitor',
    created_date    DATETIME2     NOT NULL DEFAULT GETDATE(),
    updated_date    DATETIME2     NULL
);
